From 4990aed787007c5809635fe2e059a756804bc16e Mon Sep 17 00:00:00 2001
From: Thomas Swift <tswift@u.rochester.edu>
Date: Sat, 17 Jan 2015 21:59:07 -0500
Subject: [PATCH] fix build error introduced by dcec42b


diff --git a/src/main/java/com/tswift242/tetris/TetrisPanel.java b/src/main/java/com/tswift242/tetris/TetrisPanel.java
index a621c44..9b36adc 100755
--- a/src/main/java/com/tswift242/tetris/TetrisPanel.java
+++ b/src/main/java/com/tswift242/tetris/TetrisPanel.java
@@ -44,7 +44,7 @@ public class TetrisPanel extends JPanel
 	private static final int INIT_DELAY = 400; //timer delay
 	// TODO: make this value formulaic instead of fixed in the future
 	private static final int SCORE_INCREMENT_VALUE = 100;
-	private static final int HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
+	private static final String HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
 	// maximum number of high scores to save
 	private static final int MAX_HIGH_SCORES = 10;
 	private static final String MUSIC_FILE = "/12-hans_zimmer-time.wav";
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The variable `HIGH_SCORES_FILENAME` was incorrectly declared as an `int` instead of a `String`, which caused a type mismatch and resulted in a build error when the code attempted to use it as a filename.

        Commit message:
        fix build error introduced by dcec42b  

        Patch:
         	// TODO: make this value formulaic instead of fixed in the future
 	private static final int SCORE_INCREMENT_VALUE = 100;
-	private static final int HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
+	private static final String HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
 	// maximum number of high scores to save
 	private static final int MAX_HIGH_SCORES = 10;


        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
-private static final int HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
+private static final String HIGH_SCORES_FILENAME = "TetrisHighScores.txt";

Code statements:
-private static final int HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
+private static final String HIGH_SCORES_FILENAME = "TetrisHighScores.txt";
